//! Tests for the correctly rounded transcendentals.
//!
//! # Where the reference values come from
//!
//! [`VECTORS`] was generated by evaluating each function with mpmath (BSD
//! licence; run as a black box, its source not consulted) at 4000 and at
//! 6000 bits, rounding both exactly in Python's `fractions` to the 80-bit
//! format at the listed precision and direction, and keeping a vector only
//! when the two agreed — so a value too close to a boundary for 4000 bits to
//! settle would have been caught rather than embedded. `2^n - 1` for an
//! integer `n` was computed exactly rather than through `expm1`. That is an
//! independent implementation: different algorithms (mpmath's own argument
//! reduction and series), different arithmetic, a different language.
//!
//! The arguments cover the ordinary ranges, the reduction's hard cases
//! (`pi`, `pi/2` and `2pi` rounded to 64 bits, whose sines and cosines are
//! near `2^-64`), the largest argument `FSIN` accepts, each near-exact
//! shortcut and the boundary of each, subnormal operands and results, and
//! the out-of-domain ranges of `F2XM1` and `FYL2XP1`.

use super::*;
use crate::float::Round;

/// The three precision controls, as the vector table names them.
fn pc(bits: u32) -> Precision {
    match bits {
        64 => Precision::Extended,
        53 => Precision::Double,
        _ => Precision::Single,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum F {
    Sin,
    Cos,
    Tan,
    Atan2,
    Exp2m1,
    YLog2X,
    YLog2P1X,
}

/// One expected result: `(sign_exp, sig, rounded_up)`.
type R = (u16, u64, bool);

const fn r(se: u16, sig: u64, up: bool) -> R {
    (se, sig, up)
}

/// One case: the function, `y` (ignored by the one-operand functions), `x`,
/// and the results at 64 bits in the four directions, then 53 bits to
/// nearest and 24 bits upward.
type Case = (F, u16, u64, u16, u64, [R; 6]);

const fn c(f: F, ys: u16, y: u64, xs: u16, x: u64, out: [R; 6]) -> Case {
    (f, ys, y, xs, x, out)
}

/// The precision and direction of each result in a [`Case`].
const PLAN: [(u32, Round); 6] = [
    (64, Round::TiesEven),
    (64, Round::TowardNegative),
    (64, Round::TowardPositive),
    (64, Round::TowardZero),
    (53, Round::TiesEven),
    (24, Round::TowardPositive),
];

fn eval(f: F, y: F80, x: F80, p: Precision, env: Env) -> Elementary {
    match f {
        F::Sin => sin(x, p, env),
        F::Cos => cos(x, p, env),
        F::Tan => tan(x, p, env),
        F::Atan2 => atan2(y, x, p, env),
        F::Exp2m1 => exp2m1(x, p, env),
        F::YLog2X => y_log2_x(y, x, p, env),
        F::YLog2P1X => y_log2_1p_x(y, x, p, env),
    }
}

