#[test]
fn every_vector_is_correctly_rounded_in_every_direction() {
    let mut failures = alloc::vec::Vec::new();
    for &(f, ys, y, xs, x, outs) in VECTORS {
        // Every listed result is irrational but two: F2XM1(10) = 1023 and
        // FYL2XP1(1, -0.75) = log2(1/4) = -2.
        let exact = (f == F::Exp2m1 && xs == 0x4002 && x == 0xa000_0000_0000_0000)
            || (f == F::YLog2P1X && xs == 0xbffe && x == 0xc000_0000_0000_0000);
        for (i, &(bits, round)) in PLAN.iter().enumerate() {
            let env = Env::X87.round(round);
            let got = eval(f, F80::new(ys, y), F80::new(xs, x), pc(bits), env);
            let (se, sig, up) = outs[i];
            if got.value != F80::new(se, sig)
                || got.rounded_up != up
                || got.flags.contains(Flags::INEXACT) == exact
            {
                failures.push(alloc::format!(
                    "{f:?}({ys:#06x}:{y:#018x}, {xs:#06x}:{x:#018x}) at {bits} bits {round:?}: \
                     got {:#06x}:{:#018x} up={} {:?}, want {se:#06x}:{sig:#018x} up={up}",
                    got.value.sign_exp,
                    got.value.sig,
                    got.rounded_up,
                    got.flags
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn the_constants_agree_with_independently_computed_digits() {
    // floor(pi * 2^256) and floor(ln 2 * 2^256), from mpmath at 2000 bits.
    let check = |got: Ax, hex: &str| {
        let mut want = Big::zero();
        for ch in hex.chars() {
            let d = ch.to_digit(16).unwrap();
            want = want.shl(4).add_u64(u64::from(d));
        }
        let (lo, hi) = (got.mag.sub(&got.err), got.mag.add(&got.err));
        // The true value lies in [want, want + 1) units; the enclosure has to
        // meet that interval, and be tight.
        assert_eq!(lo.cmp(&want.add_u64(1)), Ordering::Less, "{hex}: above");
        assert_ne!(hi.cmp(&want), Ordering::Less, "{hex}: below");
        assert_eq!(
            got.err.cmp(&Big::from_u64(8)),
            Ordering::Less,
            "{hex}: loose"
        );
    };
    check(
        pi(256),
        "3243f6a8885a308d313198a2e03707344a4093822299f31d0082efa98ec4e6c89",
    );
    check(
        ln2(256),
        "b17217f7d1cf79abc9e3b39803f2f6af40f343267298b62d8a0d175b8baafa2b",
    );
}

// ---------------------------------------------------------------------------
// Special operands, exact cases, flags
// ---------------------------------------------------------------------------

const X: Precision = Precision::Extended;
const ENV: Env = Env::X87;

const ONE: F80 = F80::new(0x3fff, 1 << 63);
const NEG_ONE: F80 = F80::new(0xbfff, 1 << 63);
const TWO: F80 = F80::new(0x4000, 1 << 63);
const HALF: F80 = F80::new(0x3ffe, 1 << 63);
const NEG_ZERO: F80 = F80::new(0x8000, 0);
const NEG_INF: F80 = F80::new(0xffff, 1 << 63);
const QNAN: F80 = F80::new(0x7fff, 0xc000_0000_0000_1234);
const SNAN: F80 = F80::new(0x7fff, 0x8000_0000_0000_1234);
/// An unnormal: a non-zero exponent with the integer bit clear.
const UNNORMAL: F80 = F80::new(0x3fff, 0x4000_0000_0000_0000);
/// The smallest positive subnormal.
const TINY: F80 = F80::new(0, 1);

const PI: F80 = F80::new(0x4000, 0xc90f_daa2_2168_c235);
const PI_2: F80 = F80::new(0x3fff, 0xc90f_daa2_2168_c235);
const PI_4: F80 = F80::new(0x3ffe, 0xc90f_daa2_2168_c235);
const PI_3_4: F80 = F80::new(0x4000, 0x96cb_e3f9_990e_91a8);

fn neg(v: F80) -> F80 {
    F80::new(v.sign_exp ^ 0x8000, v.sig)
}

/// A value with no exception and no rounding.
fn exact(e: Elementary, want: F80) {
    assert_eq!(e.value, want);
    assert_eq!(e.flags, Flags::NONE, "{want:?}");
    assert!(!e.rounded_up);
}

/// The invalid-operation result.
fn indefinite(e: Elementary) {
    assert_eq!(e.value, F80::INDEFINITE);
    assert!(e.flags.contains(Flags::INVALID));
}

#[test]
fn the_trigonometric_special_operands() {
    for f in [sin, tan] {
        exact(f(F80::ZERO, X, ENV), F80::ZERO);
        exact(f(NEG_ZERO, X, ENV), NEG_ZERO);
    }
    exact(cos(F80::ZERO, X, ENV), ONE);
    exact(cos(NEG_ZERO, X, ENV), ONE);
    for f in [sin, cos, tan] {
        indefinite(f(F80::INFINITY, X, ENV));
        indefinite(f(NEG_INF, X, ENV));
        indefinite(f(UNNORMAL, X, ENV));
        exact(f(QNAN, X, ENV), QNAN);
        let s = f(SNAN, X, ENV);
        assert_eq!(s.value, QNAN, "a signaling NaN comes back quiet");
        assert_eq!(s.flags, Flags::INVALID);
    }
}

#[test]
fn a_subnormal_operand_reports_denormal_and_a_tiny_result_underflows() {
    let s = sin(TINY, X, ENV);
    assert_eq!(s.value, TINY, "sin of the smallest subnormal, to nearest");
    assert!(s.rounded_up);
    assert_eq!(s.flags, Flags::DENORMAL | Flags::UNDERFLOW | Flags::INEXACT);
    // Toward zero, the result is just below the operand: zero.
    let s = sin(TINY, X, ENV.round(Round::TowardZero));
    assert_eq!(s.value, F80::ZERO);
    let c = cos(TINY, X, ENV.round(Round::TowardZero));
    assert_eq!(c.value, F80::new(0x3ffe, u64::MAX), "1 - 2^-64");
    assert_eq!(c.flags, Flags::DENORMAL | Flags::INEXACT);
}

#[test]
fn f2xm1_special_operands_and_its_three_exact_points() {
    exact(exp2m1(F80::ZERO, X, ENV), F80::ZERO);
    exact(exp2m1(NEG_ZERO, X, ENV), NEG_ZERO);
    exact(exp2m1(F80::INFINITY, X, ENV), F80::INFINITY);
    exact(exp2m1(NEG_INF, X, ENV), NEG_ONE);
    exact(exp2m1(ONE, X, ENV), ONE);
    exact(exp2m1(NEG_ONE, X, ENV), neg(HALF));
    indefinite(exp2m1(UNNORMAL, X, ENV));
    // Out of the instruction's domain: 2^20000 - 1 overflows, as the value
    // it is.
    let big = F80::new(0x3fff + 14, 0x9c40_0000_0000_0000); // 20000
    let o = exp2m1(big, X, ENV);
    assert_eq!(o.value, F80::INFINITY);
    assert_eq!(o.flags, Flags::OVERFLOW | Flags::INEXACT);
    let o = exp2m1(big, X, ENV.round(Round::TowardZero));
    assert_eq!(o.value, F80::MAX_FINITE);
    // And 2^-20000 - 1 is -1 + 2^-20000: -1 to nearest, just above it
    // upward.
    let r = exp2m1(neg(big), X, ENV);
    assert_eq!(r.value, NEG_ONE);
    assert!(r.rounded_up);
    let r = exp2m1(neg(big), X, ENV.round(Round::TowardPositive));
    assert_eq!(r.value, F80::new(0xbffe, u64::MAX));
}

#[test]
fn fpatan_follows_the_atan2_table() {
    // (y, x, result) for every special pairing in *Intel SDM* volume 2's
    // FPATAN table. A finite operand is represented by +-2.
    let f = TWO;
    let rows: &[(F80, F80, F80)] = &[
        (F80::ZERO, F80::ZERO, F80::ZERO),
        (NEG_ZERO, F80::ZERO, NEG_ZERO),
        (F80::ZERO, NEG_ZERO, PI),
        (NEG_ZERO, NEG_ZERO, neg(PI)),
        (F80::ZERO, f, F80::ZERO),
        (NEG_ZERO, f, NEG_ZERO),
        (F80::ZERO, neg(f), PI),
        (NEG_ZERO, neg(f), neg(PI)),
        (F80::ZERO, F80::INFINITY, F80::ZERO),
        (F80::ZERO, NEG_INF, PI),
        (NEG_ZERO, NEG_INF, neg(PI)),
        (f, F80::ZERO, PI_2),
        (neg(f), NEG_ZERO, neg(PI_2)),
        (f, F80::INFINITY, F80::ZERO),
        (neg(f), F80::INFINITY, NEG_ZERO),
        (f, NEG_INF, PI),
        (neg(f), NEG_INF, neg(PI)),
        (F80::INFINITY, f, PI_2),
        (NEG_INF, neg(f), neg(PI_2)),
        (F80::INFINITY, F80::ZERO, PI_2),
        (F80::INFINITY, F80::INFINITY, PI_4),
        (NEG_INF, F80::INFINITY, neg(PI_4)),
        (F80::INFINITY, NEG_INF, PI_3_4),
        (NEG_INF, NEG_INF, neg(PI_3_4)),
    ];
    for &(y, x, want) in rows {
        let r = atan2(y, x, X, ENV);
        assert_eq!(r.value, want, "atan2({y:?}, {x:?})");
        assert!(!r.flags.contains(Flags::INVALID));
        assert!(!r.flags.contains(Flags::DIV_BY_ZERO));
        // The multiples of pi are inexact and, to nearest, rounded up.
        let irrational = want.sig != 0;
        assert_eq!(r.flags.contains(Flags::INEXACT), irrational);
        assert_eq!(r.rounded_up, irrational);
    }
    let s = atan2(SNAN, ONE, X, ENV);
    assert_eq!((s.value, s.flags), (QNAN, Flags::INVALID));
    indefinite(atan2(ONE, UNNORMAL, X, ENV));
    exact(atan2(QNAN, ONE, X, ENV), QNAN);
}

#[test]
fn fyl2x_follows_its_table() {
    let f = F80::new(0x4000, 0xc000_0000_0000_0000); // 3
    let frac = HALF;
    let z = Flags::DIV_BY_ZERO;
    // (y, x, Some(result, flags)) or None for invalid.
    type Row = (F80, F80, Option<(F80, Flags)>);
    let rows: &[Row] = &[
        // x negative, either size: invalid whatever y is.
        (ONE, neg(f), None),
        (ONE, NEG_INF, None),
        (F80::ZERO, neg(frac), None),
        // x = +-0.
        (NEG_INF, F80::ZERO, Some((F80::INFINITY, Flags::NONE))),
        (neg(f), NEG_ZERO, Some((F80::INFINITY, z))),
        (F80::ZERO, F80::ZERO, None),
        (f, F80::ZERO, Some((NEG_INF, z))),
        (F80::INFINITY, NEG_ZERO, Some((NEG_INF, Flags::NONE))),
        // 0 < x < 1.
        (NEG_INF, frac, Some((F80::INFINITY, Flags::NONE))),
        (NEG_ZERO, frac, Some((F80::ZERO, Flags::NONE))),
        (F80::ZERO, frac, Some((NEG_ZERO, Flags::NONE))),
        (F80::INFINITY, frac, Some((NEG_INF, Flags::NONE))),
        (f, frac, Some((neg(f), Flags::NONE))), // 3 * log2(1/2), exactly
        // x = 1.
        (NEG_INF, ONE, None),
        (neg(f), ONE, Some((NEG_ZERO, Flags::NONE))),
        (NEG_ZERO, ONE, Some((NEG_ZERO, Flags::NONE))),
        (F80::ZERO, ONE, Some((F80::ZERO, Flags::NONE))),
        (f, ONE, Some((F80::ZERO, Flags::NONE))),
        (F80::INFINITY, ONE, None),
        // x > 1.
        (NEG_INF, f, Some((NEG_INF, Flags::NONE))),
        (NEG_ZERO, f, Some((NEG_ZERO, Flags::NONE))),
        (F80::INFINITY, f, Some((F80::INFINITY, Flags::NONE))),
        (f, TWO, Some((f, Flags::NONE))),
        // x = +inf.
        (NEG_INF, F80::INFINITY, Some((NEG_INF, Flags::NONE))),
        (neg(f), F80::INFINITY, Some((NEG_INF, Flags::NONE))),
        (F80::ZERO, F80::INFINITY, None),
        (f, F80::INFINITY, Some((F80::INFINITY, Flags::NONE))),
    ];
    for &(y, x, want) in rows {
        let r = y_log2_x(y, x, X, ENV);
        match want {
            None => indefinite(r),
            Some((v, fl)) => {
                assert_eq!(r.value, v, "{y:?} * log2 {x:?}");
                assert_eq!(r.flags, fl, "{y:?} * log2 {x:?}");
            }
        }
    }
    // A power of two is exact however large the product: 3 * log2(2^-1000).
    let r = y_log2_x(f, F80::new(0x3fff - 1000, 1 << 63), X, ENV);
    assert_eq!(r.value, F80::new(0xc00a, 0xbb80_0000_0000_0000), "-3000");
    assert_eq!(r.flags, Flags::NONE);
    // And a huge y overflows, honestly.
    let r = y_log2_x(F80::MAX_FINITE, f, X, ENV);
    assert_eq!(r.value, F80::INFINITY);
    assert_eq!(r.flags, Flags::OVERFLOW | Flags::INEXACT);
}

#[test]
fn fyl2xp1_follows_its_table() {
    let f = F80::new(0x3ffd, 0x8000_0000_0000_0000); // 0.25
    let rows: &[(F80, F80, Option<F80>)] = &[
        (NEG_INF, neg(f), Some(F80::INFINITY)),
        (NEG_INF, NEG_ZERO, None),
        (NEG_INF, F80::ZERO, None),
        (NEG_INF, f, Some(NEG_INF)),
        (neg(ONE), NEG_ZERO, Some(F80::ZERO)),
        (neg(ONE), F80::ZERO, Some(NEG_ZERO)),
        (NEG_ZERO, neg(f), Some(F80::ZERO)),
        (NEG_ZERO, f, Some(NEG_ZERO)),
        (F80::ZERO, neg(f), Some(NEG_ZERO)),
        (F80::ZERO, f, Some(F80::ZERO)),
        (ONE, NEG_ZERO, Some(NEG_ZERO)),
        (ONE, F80::ZERO, Some(F80::ZERO)),
        (F80::INFINITY, neg(f), Some(NEG_INF)),
        (F80::INFINITY, F80::ZERO, None),
        (F80::INFINITY, f, Some(F80::INFINITY)),
        // Outside the domain: 1 + x below zero is invalid.
        (ONE, F80::new(0xbfff, 0xc000_0000_0000_0000), None),
        // log2(1 + 1) and log2(1 - 1/2) are exact.
        (TWO, ONE, Some(TWO)),
        (TWO, neg(HALF), Some(neg(TWO))),
    ];
    for &(y, x, want) in rows {
        let r = y_log2_1p_x(y, x, X, ENV);
        match want {
            None => indefinite(r),
            Some(v) => {
                assert_eq!(r.value, v, "{y:?} * log2(1 + {x:?})");
                assert_eq!(r.flags, Flags::NONE, "{y:?} * log2(1 + {x:?})");
            }
        }
    }
    // x = -1: a zero argument, so a division by zero.
    let r = y_log2_1p_x(ONE, NEG_ONE, X, ENV);
    assert_eq!(r.value, NEG_INF);
    assert_eq!(r.flags, Flags::DIV_BY_ZERO);
}

// ---------------------------------------------------------------------------
// Consistency between the directions, over many arguments
// ---------------------------------------------------------------------------

/// The next representable 64-bit value above a positive finite `v`.
fn next_up(v: F80) -> F80 {
    if v.sig == u64::MAX {
        F80::new(v.sign_exp + 1, 1 << 63)
    } else {
        F80::new(v.sign_exp, v.sig + 1)
    }
}

#[test]
fn the_four_directions_bracket_one_value_on_many_arguments() {
    // For a result that is not exact, rounding down and rounding up must give
    // adjacent values with the true one between; nearest must be one of the
    // two; toward zero must be the one nearer zero; and `rounded_up` must
    // say which is which. A Ziv decision made on the wrong side of a boundary
    // breaks one of these.
    let mut seed = 0x1234_5678_9abc_def1u64;
    let mut next = || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    let mut checked = 0;
    for i in 0..280 {
        let f = i % 7;
        let r1 = next();
        let r2 = next();
        // Exponents spread over each function's interesting range.
        let span =
            |lo: i32, hi: i32, r: u64| (0x3fff + lo + (r % (hi - lo + 1) as u64) as i32) as u16;
        let sig = |r: u64| r | 1 << 63;
        let s1 = if r1 & 0x8000 != 0 { 0x8000 } else { 0 };
        let (y, x) = match f {
            0..=2 => (ONE, F80::new(s1 | span(-30, 62, r2), sig(r1))),
            3 => (
                F80::new(s1 | span(-40, 40, r1 >> 7), sig(r2)),
                F80::new(span(-40, 40, r2 >> 9), sig(r1)),
            ),
            4 => (ONE, F80::new(s1 | span(-60, -1, r2), sig(r1))),
            5 => (
                F80::new(s1 | span(-20, 20, r2 >> 3), sig(r2)),
                F80::new(span(-200, 200, r1 >> 5), sig(r1)),
            ),
            _ => (
                F80::new(s1 | span(-20, 20, r2 >> 3), sig(r2)),
                F80::new(s1 ^ (r2 as u16 & 0x8000) | span(-60, -3, r1 >> 5), sig(r1)),
            ),
        };
        let func = [
            F::Sin,
            F::Cos,
            F::Tan,
            F::Atan2,
            F::Exp2m1,
            F::YLog2X,
            F::YLog2P1X,
        ][f];
        let at = |round| eval(func, y, x, X, ENV.round(round));
        let (rn, rd, ru, rz) = (
            at(Round::TiesEven),
            at(Round::TowardNegative),
            at(Round::TowardPositive),
            at(Round::TowardZero),
        );
        assert!(rd.flags.contains(Flags::INEXACT), "{func:?} {y:?} {x:?}");
        let negative = rd.value.sign();
        let (lo_mag, hi_mag) = if negative { (ru, rd) } else { (rd, ru) };
        let lo_abs = F80::new(lo_mag.value.sign_exp & 0x7fff, lo_mag.value.sig);
        let hi_abs = F80::new(hi_mag.value.sign_exp & 0x7fff, hi_mag.value.sig);
        assert_eq!(
            next_up(lo_abs),
            hi_abs,
            "{func:?} {y:?} {x:?}: not adjacent"
        );
        assert!(
            !lo_mag.rounded_up && hi_mag.rounded_up,
            "{func:?}: direction"
        );
        assert_eq!(rz.value, lo_mag.value, "{func:?}: toward zero");
        assert!(rn.value == rd.value || rn.value == ru.value);
        assert_eq!(rn.rounded_up, rn.value == hi_mag.value);
        checked += 1;
    }
    assert_eq!(checked, 280);
}
